// กุญแจกันซ้ำเกิดตอนผู้ใช้กด และเขียนลงคิวบนดิสก์ก่อนตอบผู้ใช้
Future<void> onSubmitPressed(ScanInput input) async {
  final job = ScanJob(
    requestId: const Uuid().v4(),
    boxNo: input.boxNo,
    qty: input.qty,
  );
  await outbox.insert(job);        // SQLite บนเครื่อง
  showQueued();                    // ยังไม่บอกว่าสำเร็จ
  unawaited(syncWorker.wake());
}

// worker ลบออกจากคิวต่อเมื่อเซิร์ฟเวอร์ยืนยัน และใช้ requestId เดิมทุกครั้ง
Future<void> drain() async {
  for (final job in await outbox.pending()) {
    final res = await api.post("/scan", body: job.toJson());
    if (res.accepted) await outbox.remove(job.requestId);
    else if (res.permanentReject) await outbox.moveToDeadLetter(job, res.reason);
  }
}
